const user = $('Buscar usuário').first().json;
const events = $input.all()
  .map(i => i.json)
  .filter(e => e.id && e.start && e.start.dateTime && e.status !== 'cancelled')
  .map(e => ({ id: e.id, title: e.summary || 'Compromisso', start: e.start.dateTime }));
return [{ json: { usuario: user.usuario, offsets: user.offsets_minutes, events } }];
